using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the MCP SDK resolves this from the DI container
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city by name.")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. 'London' or 'New York'")] string city,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";

        var response = await _httpClient.GetFromJsonAsync<WeatherResponse>(url, cancellationToken);
        if (response is null)
            return $"Could not retrieve weather for '{city}'.";

        var current = response.CurrentCondition?.FirstOrDefault();
        if (current is null)
            return $"No current conditions available for '{city}'.";

        return $"""
            Weather for {city}:
              Temperature: {current.TempC}°C / {current.TempF}°F
              Feels like:  {current.FeelsLikeC}°C
              Humidity:    {current.Humidity}%
              Condition:   {current.WeatherDesc?.FirstOrDefault()?.Value ?? "Unknown"}
            """;
    }

    [McpServerTool, Description("Get a short text-based weather forecast for a city.")]
    public async Task<string> GetForecastSummary(
        [Description("City name")] string city,
        [Description("Number of forecast days (1-3)")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        days = Math.Clamp(days, 1, 3);
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=4&days={days}";

        var result = await _httpClient.GetStringAsync(url, cancellationToken);
        return string.IsNullOrWhiteSpace(result)
            ? $"No forecast available for '{city}'."
            : result;
    }
}

// Minimal DTOs for the wttr.in JSON response
public sealed class WeatherResponse
{
    [JsonPropertyName("current_condition")]
    public List<CurrentCondition>? CurrentCondition { get; set; }
}

public sealed class CurrentCondition
{
    [JsonPropertyName("temp_C")]
    public string? TempC { get; set; }

    [JsonPropertyName("temp_F")]
    public string? TempF { get; set; }

    [JsonPropertyName("FeelsLikeC")]
    public string? FeelsLikeC { get; set; }

    [JsonPropertyName("humidity")]
    public string? Humidity { get; set; }

    [JsonPropertyName("weatherDesc")]
    public List<WeatherDesc>? WeatherDesc { get; set; }
}

public sealed class WeatherDesc
{
    [JsonPropertyName("value")]
    public string? Value { get; set; }
}

